import bpy,bmesh,math
import numpy as np
from pathlib import Path
ns=bpy.app.driver_namespace['harbor_craft']
# Remove the broad subdivision added in pass 37; keep only the millimetre-scale
# original-vertex wear. Restore each editable mesh from this turn's own backup.
collections=['Coast_CraftWarehouse','Pier_Working','Harbor_Arrival_Landing']
targets={o.name:o for cn in collections for o in bpy.data.collections[cn].objects if o.type=='MESH' and o.get('natural_surface_wear')}
original_names=list(targets)
backup=ns['root']/'captures/surface_before_20261109_213235/harbor_coast_mcp.blend'
with bpy.data.libraries.load(str(backup),link=False) as (data_from,data_to):
    assert all(n in data_from.objects for n in original_names)
    data_to.objects=original_names
for name,loaded in zip(original_names,data_to.objects):
    o=targets[name];mats=list(o.data.materials);oldmesh=o.data
    o.data=loaded.data.copy();o.data.materials.clear()
    for m in mats:o.data.materials.append(m)
    bpy.data.objects.remove(loaded,do_unlink=True)
    if oldmesh.users==0:bpy.data.meshes.remove(oldmesh)
    # Original mesh already carries intermediate border vertices. Vary only those
    # borders; surface relief stays in the normal map.
    if name!='LandingDeck':
        verts=list(o.data.vertices)
        co=np.array([tuple(v.co) for v in verts]);lo=co.min(0);hi=co.max(0)
        axis=1 if name.startswith('Walkboard_') else 0
        up=2;cross=1-axis
        length=max(.001,hi[axis]-lo[axis]);width=max(.001,hi[cross]-lo[cross])
        seed=sum(ord(ch) for ch in name)
        for v in verts:
            t=(v.co[axis]-lo[axis])/length;s=(v.co[cross]-lo[cross])/width
            fade=math.sin(math.pi*max(0,min(1,t)))
            v.co[up]+=.0017*((2*s-1)**2-.5)*fade
            if seed%4==0 and t>.94 and s>.76:v.co[axis]-=.006*((t-.94)/.06)*((s-.76)/.24)
    else:
        # Landing boards are disjoint; their ends can wear without creating new faces.
        bm=bmesh.new();bm.from_mesh(o.data);unseen=set(bm.verts);groups=[]
        while unseen:
            v=unseen.pop();group=[v];queue=[v]
            while queue:
                cur=queue.pop()
                for e in cur.link_edges:
                    other=e.other_vert(cur)
                    if other in unseen:unseen.remove(other);queue.append(other);group.append(other)
            groups.append(group)
        for group in groups:
            lo=[min(v.co[i] for v in group) for i in range(3)];hi=[max(v.co[i] for v in group) for i in range(3)]
            seed=round((lo[0]+9.09)/.28)
            for v in group:
                t=(v.co.y-lo[1])/max(.001,hi[1]-lo[1]);s=(v.co.x-lo[0])/max(.001,hi[0]-lo[0])
                v.co.z+=.0017*((2*s-1)**2-.5)*math.sin(math.pi*max(0,min(1,t)))
                if seed%4==0 and t>.94 and s>.76:v.co.y-=.006*((t-.94)/.06)*((s-.76)/.24)
        bm.normal_update();bm.to_mesh(o.data);bm.free()
    o.data.update()
print('REMOVED_UNNECESSARY_SUBDIVISION',len(targets))
# Persist the normal/roughness attenuation; pass 39 only changed node strength.
for kind,scale,rs in [('boat',.56,.72),('pier',.78,.82)]:
    for suffix in ['normal','roughness']:
        path=ns['root']/'assets'/(kind+'_wood_'+suffix+'.png')
        arr=ns['image_array'](path)
        if suffix=='normal':
            n=arr[:,:,:3]*2-1;n[:,:,:2]*=scale;n/=np.linalg.norm(n,axis=2,keepdims=True);arr[:,:,:3]=n*.5+.5
        else:arr[:,:,:3]=.9+(arr[:,:,:3]-.9)*rs
        ns['png'](path,arr)
        for im in bpy.data.images:
            if Path(im.filepath).name==path.name:
                if im.packed_file:im.unpack(method='REMOVE')
                im.reload();im.pack()
print('RELIEF_ATTENUATION_SAVED')
